import React from 'react';
import { Link } from 'react-router-dom';

function HomePage() {
  return (
    <div style={{ padding: 32, textAlign: 'center' }}>
      <h1>Welcome to Cars Collection Website</h1>
      <p>Explore the world's finest cars, from supercars to classics, electrics, and concepts.</p>
      <Link to="/dashboard" style={{
        display: 'inline-block',
        marginTop: 24,
        padding: '12px 32px',
        background: '#ffb347',
        color: '#232526',
        borderRadius: 24,
        fontWeight: 600,
        textDecoration: 'none',
        fontSize: '1.2rem',
        letterSpacing: 1
      }}>
        Go to Dashboard
      </Link>
    </div>
  );
}

export default HomePage;
